css:
.relative {
  position: relative;
}
.top-\[12px\] {
  top: 12px;
}
.m-\[25px\] {
  margin: 25px;
}
.mx-\[auto\] {
  margin-left: auto;
  margin-right: auto;
}
.my-\[0\] {
  margin-top: 0;
  margin-bottom: 0;
}
.block {
  display: block;
}
.inline-block {
  display: inline-block;
}
.h-\[45px\] {
  height: 45px;
}
.h-\[6px\] {
  height: 6px;
}
.w-\[30px\] {
  width: 30px;
}
.w-\[44px\] {
  width: 44px;
}
.bg-\[\#000\] {
  --tw-bg-opacity: 1;
  background-color: rgb(0 0 0 / var(--tw-bg-opacity));
}
.p-\[5px\] {
  padding: 5px;
}
.duration-200 {
  transition-duration: 200ms;
}
.\[transition-property\:margin\2c _width\] {
  transition-property: margin, width;
}
.before\:absolute::before {
  content: var(--tw-content);
  position: absolute;
}
.before\:left-\[0\]::before {
  content: var(--tw-content);
  left: 0;
}
.before\:-mt-\[12px\]::before {
  content: var(--tw-content);
  margin-top: -12px;
}
.before\:block::before {
  content: var(--tw-content);
  display: block;
}
.before\:h-\[6px\]::before {
  content: var(--tw-content);
  height: 6px;
}
.before\:w-\[30px\]::before {
  content: var(--tw-content);
  width: 30px;
}
.before\:bg-\[\#000\]::before {
  content: var(--tw-content);
  --tw-bg-opacity: 1;
  background-color: rgb(0 0 0 / var(--tw-bg-opacity));
}
.before\:duration-200::before {
  content: var(--tw-content);
  transition-duration: 200ms;
}
.before\:content-\[\'\'\]::before {
  --tw-content: "";
  content: var(--tw-content);
}
.before\:\[transition-property\:margin\2c _width\2c _left\]::before {
  content: var(--tw-content);
  transition-property: margin, width, left;
}
.after\:absolute::after {
  content: var(--tw-content);
  position: absolute;
}
.after\:left-\[0\]::after {
  content: var(--tw-content);
  left: 0;
}
.after\:mt-\[12px\]::after {
  content: var(--tw-content);
  margin-top: 12px;
}
.after\:block::after {
  content: var(--tw-content);
  display: block;
}
.after\:h-\[6px\]::after {
  content: var(--tw-content);
  height: 6px;
}
.after\:w-\[30px\]::after {
  content: var(--tw-content);
  width: 30px;
}
.after\:bg-\[\#000\]::after {
  content: var(--tw-content);
  --tw-bg-opacity: 1;
  background-color: rgb(0 0 0 / var(--tw-bg-opacity));
}
.after\:duration-200::after {
  content: var(--tw-content);
  transition-duration: 200ms;
}
.after\:content-\[\'\'\]::after {
  --tw-content: "";
  content: var(--tw-content);
}
.after\:\[transition-property\:margin\2c _left\]::after {
  content: var(--tw-content);
  transition-property: margin, left;
}
.group:hover .group-hover\:w-\[20px\] {
  width: 20px;
}
.group:hover .group-hover\:before\:left-\[5px\]::before {
  content: var(--tw-content);
  left: 5px;
}
.group:hover .group-hover\:before\:-mt-\[6px\]::before {
  content: var(--tw-content);
  margin-top: -6px;
}
.group:hover .group-hover\:before\:w-\[10px\]::before {
  content: var(--tw-content);
  width: 10px;
}
.group:hover .group-hover\:after\:-left-\[5px\]::after {
  content: var(--tw-content);
  left: -5px;
}
.group:hover .group-hover\:after\:mt-\[6px\]::after {
  content: var(--tw-content);
  margin-top: 6px;
}
